spec_text:
---- MODULE W4Od14m4p2t1 ----
EXTENDS Naturals, FiniteSets

CONSTANTS Tasks, QCap

VARIABLES backlog, queue, active, completed

vars == <<backlog, queue, active, completed>>

Init ==
    /\ backlog = Tasks
    /\ queue = {}
    /\ active = {}
    /\ completed = {}

Enqueue(t) ==
    /\ t \in backlog
    /\ Cardinality(queue) < QCap
    /\ backlog' = backlog \ {t}
    /\ queue' = queue \cup {t}
    /\ UNCHANGED <<active, completed>>

Pickup(t) ==
    /\ t \in queue
    /\ queue' = queue \ {t}
    /\ active' = active \cup {t}
    /\ UNCHANGED <<backlog, completed>>

Finish(t) ==
    /\ t \in active
    /\ active' = active \ {t}
    /\ completed' = completed \cup {t}
    /\ UNCHANGED <<backlog, queue>>

Reissue(t) ==
    /\ t \in completed
    /\ completed' = completed \ {t}
    /\ backlog' = backlog \cup {t}
    /\ UNCHANGED <<queue, active>>

Dequeue(t) ==
    /\ t \in queue
    /\ queue' = queue \ {t}
    /\ backlog' = backlog \cup {t}
    /\ UNCHANGED <<active, completed>>

Next ==
    \/ \E t \in Tasks : Enqueue(t) \/ Pickup(t) \/ Finish(t) \/ Reissue(t) \/ Dequeue(t)

Spec == Init /\ [][Next]_vars

TasksConserved ==
    Cardinality(backlog) + Cardinality(queue) + Cardinality(active) + Cardinality(completed)
        = Cardinality(Tasks)
====

